package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class MigrationRecoveryAcceptance {
 static String route(String id){return TransferAcceptance.API+"/"+id+"/recovery";}
 static Map<String,Object> result(java.net.http.HttpResponse<byte[]> response,int status)throws Exception{return TransferAcceptance.result(response,status);}
 static Map<String,Object> post(WorkflowSupport h,String job,Object body,int status)throws Exception{return result(h.json("POST",route(job),body,auth("admin")),status);}
 static String setup(WorkflowSupport h)throws Exception{TransferAcceptance.seed();MigrationSource.tables.get("incident").getFirst().put("priority","urgent");String job=result(h.json("POST",TransferAcceptance.API,TransferAcceptance.plan(),auth("admin")),201).get("job_id").toString();TransferAcceptance.fetch(h,job);return job;}
 static Map<String,Object> corrected(){var tables=object(TransferAcceptance.plan().get("tables"));object(tables.get("incident")).put("values",map("priority",map("urgent","3")));return tables;}
 static Map<String,Object> review(WorkflowSupport h,String job,Object tables)throws Exception{return object(post(h,job,map("operation","review","tables",tables),200).get("review"));}
 static Map<String,Object> create(Object tables,Map<String,Object> reviewed,String key){return map("operation","create","tables",tables,"review",reviewed.get("review"),"confirm",true,"key",key);}
 static void run(WorkflowSupport h)throws Exception{
  String job=setup(h);assertEquals(400,h.json("POST",TransferAcceptance.API+"/"+job+"/preview",map(),auth("admin")).statusCode());var diagnostics=result(h.get(route(job)+"?table=incident",auth("admin")),200);assertEquals("mapping_error",objects(diagnostics.get("rows")).getFirst().get("status"));assertEquals("Priority must be 1–5",objects(diagnostics.get("rows")).getFirst().get("error"));assertNull(objects(diagnostics.get("rows")).getFirst().get("mapped"));var groups=result(h.get(route(job)+"?table=sys_user_group",auth("admin")),200);assertEquals("mapping_valid",objects(groups.get("rows")).getFirst().get("status"));int calls=MigrationSource.queries.size();var tables=corrected();var reviewed=review(h,job,tables);assertEquals(12,reviewed.get("rows"));assertEquals(5,((Number)reviewed.get("attachment_bytes")).intValue());assertEquals(true,object(reviewed.get("plan")).get("identities"));assertEquals(true,object(reviewed.get("plan")).get("history"));assertEquals(true,object(reviewed.get("plan")).get("attachments"));var request=create(tables,reviewed,id());var created=post(h,job,request,200);String child=created.get("child_job").toString();assertFalse(child.isEmpty());assertEquals(child,post(h,job,request,200).get("child_job"));assertEquals(calls,MigrationSource.queries.size());
  try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_record"));Map<String,Object> parent=TransferJobs.job(db,job),replay=TransferJobs.job(db,child);assertEquals("review",object(parent.get("detail")).get("status"));assertEquals("review",object(replay.get("detail")).get("status"));assertEquals(job,object(replay.get("detail")).get("replay_of"));assertFalse(object(replay.get("detail")).containsKey("previous_job"));assertFalse(object(replay.get("detail")).containsKey("resolutions"));assertEquals(map(),object(object(object(parent.get("definition")).get("tables")).get("incident")).get("values"));var source=db.all("SELECT source_table,source_id,data FROM os_transfer_item WHERE job_id=? ORDER BY source_table,source_id",job);assertEquals(source,db.all("SELECT source_table,source_id,data FROM os_transfer_item WHERE job_id=? ORDER BY source_table,source_id",child));assertArrayEquals((byte[])db.one("SELECT content FROM os_transfer_item WHERE job_id=? AND source_table='sys_attachment'",job).get("content"),(byte[])db.one("SELECT content FROM os_transfer_item WHERE job_id=? AND source_table='sys_attachment'",child).get("content"));assertEquals(2,db.count("SELECT COUNT(*) FROM os_transfer_job"));}
  new Store(h.environment);assertEquals("mapping_valid",objects(result(h.get(route(child)+"?table=incident",auth("admin")),200).get("rows")).getFirst().get("status"));result(h.json("POST",TransferAcceptance.API+"/"+child+"/preview",map(),auth("admin")),200);result(h.json("POST",TransferAcceptance.API+"/"+child+"/apply",map(),auth("admin")),200);assertEquals(child,post(h,job,request,200).get("child_job"));assertEquals(400,h.json("POST",route(child),map("operation","review","tables",tables),auth("admin")).statusCode());assertEquals(409,h.json("POST",route(job),map("operation","review","tables",tables),auth("admin")).statusCode());try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals("3",object(Service.record(db,"incident",MigrationSource.key(9)).get("data")).get("priority"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_attachment"));assertEquals(0,db.count("SELECT active FROM os_user WHERE name='ImportedAgent'"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_security_event WHERE action='migration.replayed'"));}
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  h.account("ReplayAgent","agent");String job=setup(h);assertEquals(401,h.get(route(job),null).statusCode());assertEquals(403,h.get(route(job),auth("ReplayAgent")).statusCode());assertEquals(404,h.get(route(id()),auth("admin")).statusCode());assertEquals(405,h.json("PUT",route(job),map(),auth("admin")).statusCode());for(String query:List.of("?x=y","?table=unknown","?after=bad","?table=incident&table=incident"))assertEquals(400,h.get(route(job)+query,auth("admin")).statusCode());assertEquals(400,h.json("POST",route(job)+"?table=incident",map(),auth("admin")).statusCode());String form="/admin/migrations/"+job+"/recovery";assertEquals(403,h.form(form,map("operation","review","tables","{}"),auth("admin")).statusCode());assertEquals(400,h.protectedForm(form,map("operation","review","tables","{"),auth("admin")).statusCode());assertEquals(200,h.get(form,auth("admin")).statusCode());
  for(var body:List.of(map(),map("operation","unknown"),map("operation","review"),map("operation","review","tables",corrected(),"extra",true),map("operation","review","tables",map()),map("operation","review","tables",List.of()))){assertEquals(400,h.json("POST",route(job),body,auth("admin")).statusCode());}for(int n=0;n<7;n++){var tables=corrected();var mapping=object(tables.get("incident"));switch(n){case 0->mapping.put("target","sc_request");case 1->mapping.put("fields",map("short_description","not_fetched"));case 2->mapping.put("fields",map("unknown_destination","short_description"));case 3->mapping.put("fields",map());case 4->mapping.put("extra",true);case 5->mapping.put("values",map("unmapped",map("x","y")));case 6->mapping.put("values",map("priority",map("urgent",3)));}assertEquals(400,h.json("POST",route(job),map("operation","review","tables",tables),auth("admin")).statusCode());}var tables=corrected();tables.put("incident","scalar");assertEquals(400,h.json("POST",route(job),map("operation","review","tables",tables),auth("admin")).statusCode());
  var reviewed=review(h,job,corrected());for(var field:List.of(Map.entry("key","bad"),Map.entry("confirm",false),Map.entry("extra",true))){var request=create(corrected(),reviewed,id());request.put(field.getKey(),field.getValue());assertEquals(400,h.json("POST",route(job),request,auth("admin")).statusCode());}var request=create(corrected(),reviewed,id());request.put("review","stale");assertEquals(409,h.json("POST",route(job),request,auth("admin")).statusCode());var reviewedForm=h.protectedForm(form,map("operation","review","tables",JSON.writeValueAsString(corrected())),auth("admin"));assertEquals(200,reviewedForm.statusCode());var formRequest=create(JSON.writeValueAsString(corrected()),reviewed,id());formRequest.put("confirm","false");assertEquals(400,h.protectedForm(form,formRequest,auth("admin")).statusCode());formRequest.put("confirm","true");assertEquals(200,h.protectedForm(form,formRequest,auth("admin")).statusCode());
 }
 static void changes(WorkflowSupport h)throws Exception{
  String job=setup(h);var tables=corrected();var reviewed=review(h,job,tables);try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE name='admin'");db.connection.commit();}assertEquals(409,h.json("POST",route(job),create(tables,reviewed,id()),auth("admin")).statusCode());Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"incident");}reviewed=review(h,job,tables);var changed=new LinkedHashMap<>(original);changed.put("label","Changed incident schema");ReferencePickerAcceptance.writeSchema(h,"incident",changed);assertEquals(409,h.json("POST",route(job),create(tables,reviewed,id()),auth("admin")).statusCode());ReferencePickerAcceptance.writeSchema(h,"incident",original);for(String operation:List.of("read","create")){changed=new LinkedHashMap<>(original);changed.put("record_roles",map(operation,List.of("agent")));ReferencePickerAcceptance.writeSchema(h,"incident",changed);assertEquals(403,h.get(route(job),auth("admin")).statusCode());ReferencePickerAcceptance.writeSchema(h,"incident",original);}
  reviewed=review(h,job,tables);try(var db=h.store.open()){var row=db.one("SELECT data FROM os_transfer_item WHERE job_id=? AND source_table='incident'",job);object(row.get("data")).put("short_description","Changed source snapshot");db.update("UPDATE os_transfer_item SET data="+db.jsonParameter()+" WHERE job_id=? AND source_table='incident'",JSON.writeValueAsString(row.get("data")),job);db.connection.commit();}assertEquals(409,h.json("POST",route(job),create(tables,reviewed,id()),auth("admin")).statusCode());
  reviewed=review(h,job,tables);try(var db=h.store.open()){db.update("UPDATE os_transfer_job SET source_url='https://not-allowed.example' WHERE job_id=?",job);var row=TransferJobs.job(db,job);object(row.get("definition")).put("source","https://not-allowed.example");db.update("UPDATE os_transfer_job SET definition="+db.jsonParameter()+" WHERE job_id=?",JSON.writeValueAsString(row.get("definition")),job);db.connection.commit();}assertEquals(400,h.json("POST",route(job),create(tables,reviewed,id()),auth("admin")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_transfer_job SET source_url=? WHERE job_id=?",MigrationSource.origin(),job);var row=TransferJobs.job(db,job);object(row.get("definition")).put("source",MigrationSource.origin());db.update("UPDATE os_transfer_job SET definition="+db.jsonParameter()+" WHERE job_id=?",JSON.writeValueAsString(row.get("definition")),job);db.connection.commit();}
  var request=create(tables,review(h,job,tables),id());try(var db=h.store.open()){db.update("CREATE UNIQUE INDEX fixture_replay_copy_failure ON os_transfer_item(source_table,source_id)");db.connection.commit();}assertEquals(500,h.json("POST",route(job),request,auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_transfer_job"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_security_event WHERE action='migration.replayed'"));assertFalse(object(TransferJobs.job(db,job).get("detail")).containsKey("mapping_replays"));db.update("DROP INDEX fixture_replay_copy_failure");db.connection.commit();}String child;try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var first=pool.submit(()->post(h,job,request,200).get("child_job"));var second=pool.submit(()->post(h,job,request,200).get("child_job"));child=first.get().toString();assertEquals(child,second.get());}var mismatch=new LinkedHashMap<>(request);mismatch.put("review","different");assertEquals(409,h.json("POST",route(job),mismatch,auth("admin")).statusCode());mismatch=new LinkedHashMap<>(request);mismatch.put("tables",object(TransferAcceptance.plan().get("tables")));assertEquals(409,h.json("POST",route(job),mismatch,auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(2,db.count("SELECT COUNT(*) FROM os_transfer_job"));var row=TransferJobs.job(db,child);var state=object(row.get("detail"));state.put("status","fetching");TransferJobs.save(db,child,state);db.connection.commit();}assertEquals(400,h.get(route(child),auth("admin")).statusCode());
 }
 static void paging(WorkflowSupport h)throws Exception{
  String job=setup(h);try(var db=h.store.open()){for(int n=100;n<205;n++)db.update("INSERT INTO os_transfer_item(job_id,source_table,source_id,data) VALUES(?,'incident',?,"+db.jsonParameter()+")",job,MigrationSource.key(n),JSON.writeValueAsString(map("sys_id",MigrationSource.key(n),"short_description","Paged source "+n,"state","1","priority","3")));db.connection.commit();}var first=result(h.get(route(job)+"?table=incident",auth("admin")),200);assertEquals(100,objects(first.get("rows")).size());assertNotNull(first.get("next_after"));var second=result(h.get(route(job)+"?table=incident&after="+first.get("next_after"),auth("admin")),200);assertEquals(6,objects(second.get("rows")).size());assertNull(second.get("next_after"));var none=result(h.get(route(job)+"?table=incident&after="+"f".repeat(32),auth("admin")),200);assertTrue(objects(none.get("rows")).isEmpty());var ids=new HashSet<Object>();for(var row:objects(first.get("rows")))assertTrue(ids.add(row.get("source_id")));for(var row:objects(second.get("rows")))assertTrue(ids.add(row.get("source_id")));
 }
 static void snapshotBounds(WorkflowSupport h)throws Exception{
  String job=setup(h);String large="x".repeat(524288);try(var db=h.store.open()){for(int n=1000;n<1101;n++)db.update("INSERT INTO os_transfer_item(job_id,source_table,source_id,data) VALUES(?,'incident',?,"+db.jsonParameter()+")",job,MigrationSource.key(n),JSON.writeValueAsString(map("body",large)));db.connection.commit();}assertEquals(400,h.json("POST",route(job),map("operation","review","tables",corrected()),auth("admin")).statusCode());try(var db=h.store.open()){db.update("DELETE FROM os_transfer_item WHERE job_id=? AND source_table='incident' AND source_id<>?",job,MigrationSource.key(9));db.update("UPDATE os_transfer_item SET content=? WHERE job_id=? AND source_table='sys_attachment'",new byte[50*1024*1024+1],job);db.connection.commit();}assertEquals(400,h.json("POST",route(job),map("operation","review","tables",corrected()),auth("admin")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_transfer_item SET content=? WHERE job_id=? AND source_table='sys_attachment'","proof".getBytes(java.nio.charset.StandardCharsets.UTF_8),job);for(int n=1000;n<11000;n++)db.update("INSERT INTO os_transfer_item(job_id,source_table,source_id,data) VALUES(?,'incident',?,'{}')",job,MigrationSource.key(n));db.connection.commit();}assertEquals(400,h.json("POST",route(job),map("operation","review","tables",corrected()),auth("admin")).statusCode());
 }
 static void capacities(WorkflowSupport h)throws Exception{
  String job=setup(h);try(var db=h.store.open()){var parent=TransferJobs.job(db,job);var detail=object(parent.get("detail"));var replays=map();for(int n=0;n<20;n++)replays.put(id(),map("child_job",id()));detail.put("mapping_replays",replays);TransferJobs.save(db,job,detail);db.connection.commit();}var request=create(corrected(),review(h,job,corrected()),id());assertEquals(400,h.json("POST",route(job),request,auth("admin")).statusCode());try(var db=h.store.open()){var parent=TransferJobs.job(db,job);var detail=object(parent.get("detail"));detail.remove("mapping_replays");TransferJobs.save(db,job,detail);for(int n=1;n<1000;n++)db.update("INSERT INTO os_transfer_job(job_id,source_url,creator_id,definition,detail,created) VALUES(?,'https://fixture.example','actor',?,?,?)",id(),JSON.writeValueAsString(parent.get("definition")),JSON.writeValueAsString(map("status","review","phase",0,"cursor","","generation",0)),now());db.connection.commit();}request=create(corrected(),review(h,job,corrected()),id());assertEquals(400,h.json("POST",route(job),request,auth("admin")).statusCode());
 }
}
